DO $$ DECLARE a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); denied boolean:=false; BEGIN BEGIN INSERT INTO public.security_scan_runs(id,status,trigger,source,high_regression,findings,created_at) VALUES(a,'ok','test','test',true,'[{"id":"qa-high","package":"qa-package","severity":"high"}]',now()+interval '1 day'); IF public.unresolved_catalog_security_scan() IS DISTINCT FROM a THEN RAISE EXCEPTION 'New high must block'; END IF; INSERT INTO public.security_scan_runs(id,status,trigger,source,high_regression,findings,created_at) VALUES(b,'ok','test','test',false,'[{"id":"qa-high","package":"qa-package","severity":"high"}]',now()+interval '2 days'); IF public.unresolved_catalog_security_scan() IS DISTINCT FROM a THEN RAISE EXCEPTION 'Repeated high must remain blocked'; END IF; BEGIN UPDATE public.products SET name=name WHERE id='00000000-0000-0000-0000-000000000000'; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Catalog statement gate failed'; END IF; INSERT INTO public.catalog_security_approvals(scan_id,approved_by,reason) VALUES(a,gen_random_uuid(),'Isolated approval fixture'); IF public.unresolved_catalog_security_scan()=a THEN RAISE EXCEPTION 'Approval failed'; END IF; RAISE EXCEPTION USING ERRCODE='ZX001', MESSAGE='Verified; rollback fixtures'; EXCEPTION WHEN SQLSTATE 'ZX001' THEN RAISE NOTICE 'Sticky gate, statement denial and approval verified; fixtures rolled back'; END; END $$;